CREATE TABLE `disponibilidad` (
  `id_disponibilidad` int NOT NULL AUTO_INCREMENT,
  `fecha` date NOT NULL,
  `precio` decimal(10,2) DEFAULT NULL,
  `estado` enum('disponible','reservada','cerrada','booking','airbnb') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'disponible',
  `cancelable` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = cancelable, 0 = solo tarifa no cancelable',
  `fuente` enum('local','booking','airbnb') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'local',
  `id_reserva` int DEFAULT NULL,
  `actualizado` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_disponibilidad`),
  UNIQUE KEY `fecha` (`fecha`),
  KEY `id_reserva` (`id_reserva`),
  CONSTRAINT `disponibilidad_ibfk_1` FOREIGN KEY (`id_reserva`) REFERENCES `reservas` (`id_reserva`)
) ENGINE=InnoDB AUTO_INCREMENT=15036461 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
